import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { diffSnapshots, hasChanges } from "../src/diff.js";
import { parseSnapshot } from "../src/snapshot.js";
import { FIXTURES, loadVault } from "./helpers.js";

// The vault example's `deposit_emits_event` snapshot, generated by soroban-sdk
// 30.0.0-rc.1 from the same contract and test as the `vault-fee/head` fixture
// (soroban-sdk 29.0.1).
const SDK30 = join(FIXTURES, "sdk-30", "deposit_emits_event.1.json");

describe("soroban-sdk 30.0.0-rc.1 snapshots", () => {
  const sdk29 = loadVault("head", "deposit_emits_event");
  const sdk30 = parseSnapshot(readFileSync(SDK30, "utf8"), SDK30);

  it("parse without errors", () => {
    expect(sdk30.ledger.protocol_version).toBe(30);
    expect(sdk30.ledger.ledger_entries.length).toBe(sdk29.ledger.ledger_entries.length);
  });

  it("differ from the SDK 29 output only in the protocol version", () => {
    const d = diffSnapshots(sdk29, sdk30);
    expect(hasChanges(d)).toBe(true);
    expect(d.env).toEqual([{ field: "protocol_version", before: "29", after: "30" }]);
    expect(d.storage).toEqual([]);
    const edits = (lines: { op: string }[]) => lines.filter((l) => l.op !== " ");
    expect(edits(d.events)).toEqual([]);
    expect(edits(d.auth)).toEqual([]);
  });
});
